# Run from the repo root, after orange_route_trainers.py.
# New battle pictures for the Orange leaders, drawn from anime references:
#   Cissy  - RS Beauty base: red-brown spiky ponytail, black top, long coral skirt with pocket, white shoes
#   Danny  - Brawly base: red hair, red Hawaiian shirt, violet shorts, tanned
#   Rudy   - Rich Boy base: brown hair, black shirt and trousers, cream vest, hand at his face
#   Luana  - RS Aroma Lady base: red hair, yellow cardigan, blue dress, sandals
# Each uses its base picture's animation entry.
import base64, re
PNG = {'cissy': '', 'danny': '', 'rudy': '', 'luana': ''}
for k, b in PNG.items():
    open('graphics/trainers/front_pics/%s_front_pic.png' % k, 'wb').write(base64.b64decode(b))
p = 'src/data/trainer_graphics/front_pic_anims.h'; s = open(p, encoding='utf-8').read()
for k, new in [('CISSY', 'sAnims_RSBeauty'), ('DANNY', 'sAnims_LeaderBrawly'), ('RUDY', 'sAnims_RichBoy'), ('LUANA', 'sAnims_RSAromaLady')]:
    s, n = re.subn(r'(\[TRAINER_PIC_%s\]\s*=\s*)\w+,' % k, r'\g<1>%s,' % new, s); assert n == 1, k
open(p, 'w', newline='\n', encoding='utf-8').write(s)
print('orange leader pics ok')
